    "exp-candy-s": "经验糖果S", "exp-candy-m": "经验糖果M", "exp-candy-xl": "经验糖果XL", "exp-candy-big": "经验糖果特大", "coin": "代币", "gracidea": "葛拉西蒂亚花",
